using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Staff.Subway;
namespace Staff.Rendering.Editor {
[InitializeOnLoad] public static class ModeDemoCapture {
 const string W="Library/ModeDemo/";
 static ModeDemoCapture(){EditorApplication.update+=Poll;}
 static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||!File.Exists(W+"capture.request"))return;File.Delete(W+"capture.request");try{if(EditorApplication.isPlaying&&!SceneManager.GetSceneByPath(Staff.Shared.SceneTravel.City).isLoaded){CaptureLab();return;}Run();File.WriteAllText(W+"result.txt","PASS city mode video frames, Animation Lab thumbnail, time transition continuity\n");}catch(Exception e){File.WriteAllText(W+"error.txt",e.ToString());}}
 static void Run(){Directory.CreateDirectory(W+"frames");var active=SceneManager.GetActiveScene();var city=SceneManager.GetSceneByPath(Staff.Shared.SceneTravel.City);bool loaded=city.isLoaded;if(!loaded)city=EditorSceneManager.OpenScene(Staff.Shared.SceneTravel.City,OpenSceneMode.Additive);var source=city.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<AbstractEnvironment>(true)).First();var previousMode=source.Mode;source.SetMode(AbstractEnvironment.EnvironmentMode.Real);var go=new GameObject("Temporary mode demo camera");SceneManager.MoveGameObjectToScene(go,city);var camera=go.AddComponent<Camera>();camera.CopyFrom(source.GetComponent<Camera>());camera.enabled=false;camera.transform.position=new Vector3(-18,12,-20);camera.transform.LookAt(new Vector3(0,3,25));camera.fieldOfView=64;camera.GetUniversalAdditionalCameraData().SetRenderer(0);camera.overrideSceneCullingMask=EditorSceneManager.GetSceneCullingMask(city);var mode=go.AddComponent<AbstractEnvironment>();mode.environmentRoot=source.environmentRoot;mode.additionalEnvironmentRoots=source.additionalEnvironmentRoots;mode.surfaceShader=source.surfaceShader;mode.geometryShader=source.geometryShader;mode.edgeShader=source.edgeShader;mode.analyticShader=source.analyticShader;mode.abstractSkybox=source.abstractSkybox;mode.enabled=true;if(!mode.environmentRoot||!mode.edgeShader)throw new Exception("Missing city environment references");
 try{var train=city.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Staff.Shared.SubwayConsist>(true)).First();var bounds=new Bounds(train.transform.position,Vector3.zero);foreach(var r in train.GetComponentsInChildren<Renderer>())bounds.Encapsulate(r.bounds);var savedPosition=camera.transform.position;var savedRotation=camera.transform.rotation;camera.transform.position=bounds.center+new Vector3(-48,22,-58);camera.transform.LookAt(bounds.center+new Vector3(0,-5,0));Capture(camera,"docs/MathCity/City-Street.png",1440,810);camera.transform.SetPositionAndRotation(savedPosition,savedRotation);
 int frame=0;var start=typeof(AbstractEnvironment).GetField("entryStart",BindingFlags.NonPublic|BindingFlags.Instance);Vector3 origin=city.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Staff.Characters.AdventurePlayer>(true)).First().transform.position;
 foreach(var target in new[]{AbstractEnvironment.EnvironmentMode.Abstract,AbstractEnvironment.EnvironmentMode.Imaginary,AbstractEnvironment.EnvironmentMode.Real}){for(int i=0;i<8;i++)Capture(camera,W+"frames/"+(frame++).ToString("D4")+".png",960,540);mode.BeginTransition(target,origin);if(!mode.IsEntering)throw new Exception("Transition did not begin: "+target);for(int i=0;i<24;i++){start.SetValue(mode,Time.unscaledTime-mode.entryDuration*i/23f);Capture(camera,W+"frames/"+(frame++).ToString("D4")+".png",960,540);}mode.SetMode(target);}
 var sky=city.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<SubwayTimeOfDay>(true)).First();int old=sky.Current;try{sky.SetMode(1);float before=sky.atmosphere.Elevation;int rebuilds=sky.atmosphere.RebuildCount;sky.TransitionToMode(2);if(sky.atmosphere.RebuildCount!=rebuilds)throw new Exception("Transition start rebuilt atmosphere at another time");if(Mathf.Abs(sky.atmosphere.Elevation-before)>.01f)throw new Exception("Time transition snapped on start");sky.AdvanceTimeTransition(sky.timeTransitionSeconds*.5f);float middle=sky.atmosphere.Elevation;if(!(middle<before&&middle>sky.presets[2].elevation))throw new Exception("Sky interpolation not between endpoints");sky.AdvanceTimeTransition(sky.timeTransitionSeconds);if(sky.IsTimeTransitioning||sky.Current!=2)throw new Exception("Sky transition did not finish");}finally{sky.SetMode(old);}
 }finally{mode.SetMode(AbstractEnvironment.EnvironmentMode.Real);UnityEngine.Object.DestroyImmediate(go);source.SetMode(previousMode);if(!loaded)EditorSceneManager.CloseScene(city,true);SceneManager.SetActiveScene(active);}
 CaptureLab();}
 static void CaptureLab(){var active=SceneManager.GetActiveScene();var cursorLock=Cursor.lockState;bool cursorVisible=Cursor.visible;bool preview=Application.isPlaying;var lab=preview?EditorSceneManager.OpenPreviewScene("Assets/StaffAnimationLab/Scenes/Animation Test.unity"):EditorSceneManager.OpenScene("Assets/StaffAnimationLab/Scenes/Animation Test.unity",OpenSceneMode.Additive);try{var player=lab.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Staff.AnimationLab.AnimationLabPlayer>(true)).First();typeof(Staff.AnimationLab.AnimationLabPlayer).GetMethod("Start",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(player,null);player.viewCamera.overrideSceneCullingMask=EditorSceneManager.GetSceneCullingMask(lab);foreach(var root in lab.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))t.gameObject.layer=30;player.viewCamera.cullingMask=1<<30;player.viewCamera.rect=new Rect(0,0,1,1);player.viewCamera.clearFlags=CameraClearFlags.SolidColor;player.viewCamera.backgroundColor=new Color(.08f,.10f,.14f);player.viewCamera.transform.position=new Vector3(1.5f,1.4f,3.5f);player.viewCamera.transform.LookAt(new Vector3(0,1,0));Directory.CreateDirectory("Assets/StaffShared/Resources/SceneThumbnails");Capture(player.viewCamera,"Assets/StaffShared/Resources/SceneThumbnails/Animation Test.png",440,248);}finally{if(preview)EditorSceneManager.ClosePreviewScene(lab);else EditorSceneManager.CloseScene(lab,true);SceneManager.SetActiveScene(active);Cursor.lockState=cursorLock;Cursor.visible=cursorVisible;}AssetDatabase.Refresh();}
 static void Capture(Camera c,string path,int width,int height){var target=c.targetTexture;var rt=new RenderTexture(width,height,24,RenderTextureFormat.ARGBHalf);var prior=RenderTexture.active;Texture2D tex=null,png=null;try{c.targetTexture=rt;StaffCameraCapture.Render(c);RenderTexture.active=rt;tex=new Texture2D(width,height,TextureFormat.RGBAFloat,false,true);tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();png=new Texture2D(width,height,TextureFormat.RGB24,false);png.SetPixels(tex.GetPixels().Select(x=>x.gamma).ToArray());png.Apply();File.WriteAllBytes(path,png.EncodeToPNG());}finally{c.targetTexture=target;RenderTexture.active=prior;if(tex)UnityEngine.Object.DestroyImmediate(tex);if(png)UnityEngine.Object.DestroyImmediate(png);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
 }
}
